<script setup lang="ts">
import{onBeforeUnmount,reactive,ref}from'vue';import{useRouter}from'vue-router';import{api,login,type ApiResponse}from'@whaashop/shared';import BrandLogo from'../components/BrandLogo.vue';
type Mode='login'|'register'|'forgot';const mode=ref<Mode>('login'),error=ref(''),message=ref(''),busy=ref(false),countdown=ref(0),router=useRouter();const form=reactive({username:'',email:'',nickname:'',password:'',confirmPassword:'',code:''});let timer:number|undefined;
function change(value:Mode){mode.value=value;error.value='';message.value='';form.password='';form.confirmPassword='';form.code=''}function validate(){if(form.username.trim().length<3)throw new Error('用户名至少 3 个字符');if(mode.value!=='login'&&!/^\S+@\S+\.\S+$/.test(form.email))throw new Error('请输入正确的邮箱');if(mode.value==='register'&&!form.nickname.trim())throw new Error('请输入昵称');if(form.password.length<6)throw new Error('密码至少 6 个字符');if(mode.value!=='login'&&form.password!==form.confirmPassword)throw new Error('两次输入的密码不一致');if(mode.value==='forgot'&&!/^\d{6}$/.test(form.code))throw new Error('请输入 6 位验证码')}
async function submit(){error.value='';message.value='';busy.value=true;try{validate();if(mode.value==='login'){const user=await login(form.username,form.password);if(user.role!=='USER')throw new Error('管理员请使用管理后台');return router.push('/')}if(mode.value==='register'){await api.post('/auth/register',{username:form.username,email:form.email,nickname:form.nickname,password:form.password});await login(form.username,form.password);return router.push('/')}await api.post('/auth/password-reset',{username:form.username,email:form.email,code:form.code,password:form.password});message.value='密码已重置，请使用新密码登录';change('login');message.value='密码已重置，请使用新密码登录'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function sendCode(){error.value='';if(form.username.trim().length<3)return error.value='请先输入用户名';if(!/^\S+@\S+\.\S+$/.test(form.email))return error.value='请先输入正确的邮箱';busy.value=true;try{await api.post<ApiResponse<void>>('/auth/password-reset/code',{username:form.username,email:form.email});message.value='如果用户名与邮箱匹配，验证码将发送到邮箱';countdown.value=60;timer=window.setInterval(()=>{if(--countdown.value<=0)clearInterval(timer)},1000)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}onBeforeUnmount(()=>clearInterval(timer));
</script>
<template><div class="auth-page"><section class="auth-card"><div class="auth-brand"><BrandLogo tagline="WELCOME HOME"/><h1>{{mode==='login'?'欢迎回来':mode==='register'?'创建新账号':'找回登录密码'}}</h1><p>{{mode==='login'?'登录后继续你的精选生活':mode==='register'?'邮箱和用户名都将作为账号唯一标识':'通过注册邮箱验证身份'}}</p></div><div class="tabs"><button :class="{active:mode==='login'}" @click="change('login')">登录</button><button :class="{active:mode==='register'}" @click="change('register')">注册</button></div><form @submit.prevent="submit"><label><span>用户名</span><input v-model="form.username" maxlength="30" autocomplete="username" placeholder="3-30 个字符"></label><label v-if="mode!=='login'"><span>邮箱</span><input v-model="form.email" type="email" maxlength="120" autocomplete="email" placeholder="name@example.com"></label><label v-if="mode==='register'"><span>昵称</span><input v-model="form.nickname" maxlength="50" placeholder="商城中展示的名称"></label><label v-if="mode==='forgot'"><span>邮箱验证码</span><div class="code-field"><input v-model="form.code" maxlength="6" inputmode="numeric" placeholder="6 位数字"><button type="button" :disabled="busy||countdown>0" @click="sendCode">{{countdown?`${countdown}s`:'发送验证码'}}</button></div></label><label><span>{{mode==='forgot'?'新密码':'密码'}}</span><input v-model="form.password" type="password" minlength="6" maxlength="64" :autocomplete="mode==='login'?'current-password':'new-password'" placeholder="至少 6 个字符"></label><label v-if="mode!=='login'"><span>确认密码</span><input v-model="form.confirmPassword" type="password" minlength="6" maxlength="64" autocomplete="new-password" placeholder="再次输入密码"></label><p v-if="error" class="notice error">{{error}}</p><p v-if="message" class="notice">{{message}}</p><button class="submit" :disabled="busy">{{busy?'正在处理…':mode==='login'?'登录':mode==='register'?'注册并登录':'重置密码'}}</button></form><button v-if="mode==='login'" class="forgot" @click="change('forgot')">忘记密码？</button><button v-else-if="mode==='forgot'" class="forgot" @click="change('login')">返回登录</button></section></div></template>
<style scoped>.auth-page{min-height:calc(100vh - 140px);display:grid;place-items:center;padding:48px 20px;background:radial-gradient(circle at 50% 0,#ffedd5 0,transparent 38%)}.auth-card{width:min(460px,100%);padding:34px 38px;border:1px solid #f2dfd1;border-radius:24px;background:#fff;box-shadow:0 25px 70px #7c2d1217}.auth-brand{text-align:center}.auth-brand :deep(.brand-logo){justify-content:center}.auth-brand h1{margin:25px 0 8px;font-size:28px}.auth-brand p{margin:0;color:#9a7660;font-size:13px}.tabs{display:grid;grid-template-columns:1fr 1fr;margin:25px 0 18px;padding:4px;border-radius:12px;background:#fff7ed}.tabs button{padding:10px;border:0;border-radius:9px;background:transparent;color:#9a7660;cursor:pointer}.tabs button.active{background:#fff;color:#ea580c;font-weight:800;box-shadow:0 3px 12px #7c2d1212}label{display:block;margin:13px 0}label>span{display:block;margin-bottom:6px;font-size:12px;font-weight:700;color:#664737}input{width:100%;padding:12px 13px;border:1px solid #ead8ca;border-radius:10px;outline:0}input:focus{border-color:#f97316;box-shadow:0 0 0 3px #ffedd5}.code-field{display:flex;gap:8px}.code-field button{flex:none;padding:0 13px;border:1px solid #fed7aa;border-radius:10px;background:#fff7ed;color:#ea580c;cursor:pointer}.submit{width:100%;margin-top:10px;padding:13px;border:0;border-radius:11px;background:linear-gradient(135deg,#fb923c,#ea580c);color:#fff;font-weight:800;cursor:pointer}.submit:disabled,.code-field button:disabled{opacity:.6;cursor:not-allowed}.forgot{display:block;margin:16px auto 0;border:0;background:none;color:#c2410c;cursor:pointer}.notice{padding:10px;border-radius:8px;background:#ecfdf5;color:#047857;font-size:12px}.notice.error{background:#fef2f2;color:#dc2626}@media(max-width:520px){.auth-card{padding:27px 22px}}</style>
